/**
 * The live evidence report — generated by Gemini (free tier).
 *
 * One grounded call turns the measured checker result + the exploit source into
 * the plain-language report the company reads (interface #3). The facts come
 * from the fork; the model only describes them — it never decides the severity
 * that triggers a payout.
 *
 * Guarantees the demo depends on (unchanged by the provider swap):
 *   - No API key        -> canned fallback, no call attempted.
 *   - Error / bad JSON   -> canned fallback, flagged.
 *   - Hard timeout       -> canned fallback.
 * We validate Gemini's JSON against the same Zod schema before trusting it.
 */
import { GoogleGenAI, Type } from "@google/genai";
import { env } from "../env.js";
import type { CheckerResult, EvidenceReport } from "../types.js";
import { cannedReport } from "./fallback.js";
import { ReportSchema } from "./schema.js";

let client: GoogleGenAI | null = null;
function getClient(): GoogleGenAI {
  if (!client) client = new GoogleGenAI({ apiKey: env.geminiApiKey });
  return client;
}

/** Gemini response schema — the five report fields, in order. */
const responseSchema = {
  type: Type.OBJECT,
  properties: {
    summary: { type: Type.STRING },
    steps: { type: Type.ARRAY, items: { type: Type.STRING } },
    rootCause: { type: Type.STRING },
    suggestedSeverity: { type: Type.STRING, enum: ["critical", "high", "medium"] },
    suggestedFixSummary: { type: Type.STRING },
  },
  required: ["summary", "steps", "rootCause", "suggestedSeverity", "suggestedFixSummary"],
  propertyOrdering: [
    "summary",
    "steps",
    "rootCause",
    "suggestedSeverity",
    "suggestedFixSummary",
  ],
};

function buildPrompt(checker: CheckerResult, exploitSource: string): string {
  return [
    "You are writing a short evidence report for a company that received a",
    "security bug report. A checker already ran the attack on a copy of the",
    "chain and measured the result — those numbers below are the ground truth.",
    "Describe what happened in plain language a non-technical reader can follow.",
    "Do NOT decide what gets paid; `suggestedSeverity` is only your opinion for",
    "the company to weigh.",
    "",
    "Measured checker result (ground truth):",
    JSON.stringify(
      {
        ruleBroken: checker.ruleBroken,
        severityFromRule: checker.severity,
        valueMovedUsdc: checker.valueMovedUsdc,
      },
      null,
      2,
    ),
    "",
    "The submitted exploit source:",
    "```solidity",
    exploitSource.slice(0, 8000),
    "```",
  ].join("\n");
}

export async function generateReport(
  checker: CheckerResult,
  exploitSource: string,
): Promise<EvidenceReport> {
  if (!env.geminiApiKey) {
    return cannedReport(checker);
  }

  // Hard timeout that actually cancels the request (frees the socket so the
  // process isn't held open, and so a slow model never lingers).
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), env.aiTimeoutMs);
  try {
    const res = await getClient().models.generateContent({
      model: env.geminiModel,
      contents: buildPrompt(checker, exploitSource),
      config: {
        responseMimeType: "application/json",
        responseSchema,
        // The report is short and grounded — no reasoning needed. Disabling
        // thinking makes a flash model answer in a couple of seconds instead of
        // tens, which keeps the demo snappy.
        thinkingConfig: { thinkingBudget: 0 },
        abortSignal: controller.signal,
      },
    });

    const text = res.text;
    if (!text) {
      console.error("[ai] gemini returned no text; using fallback");
      return cannedReport(checker);
    }

    // Validate against our schema before trusting the model's JSON.
    const parsed = ReportSchema.safeParse(JSON.parse(text));
    if (!parsed.success) {
      console.error("[ai] gemini output failed schema validation; using fallback");
      return cannedReport(checker);
    }
    return { ...parsed.data, fallback: false };
  } catch (err) {
    console.error("[ai] report generation failed; using fallback:", err);
    return cannedReport(checker);
  } finally {
    clearTimeout(timer);
  }
}
